func main() {
	reader := bufio.NewReader(os.Stdin)
	k := readInt(reader)
	grid := make([]string, 4)
	for i := 0; i < 4; i++ {
		grid[i] = readLine(reader)
	}

	// Count the number of panels for each time (1-9)
	count := make([]int, 10) // index 0 unused
	for _, row := range grid {
		for _, c := range row {
			if c >= '1' && c <= '9' {
				t := int(c - '0')
				count[t]++
			}
		}
	}

	// Check each time
	possible := true
	for t := 1; t <= 9; t++ {
		if count[t] > 2*k {
			possible = false
			break
		}
	}

	if possible {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

func readInt(reader *bufio.Reader) int {
	line, _ := reader.ReadString('\n')
	var num int
	fmt.Sscanf(line, "%d", &num)
	return num
}

func readLine(reader *bufio.Reader) string {
	line, _ := reader.ReadString('\n')
	// Trim newline characters
	line = line[:len(line)-1]
	if len(line) > 0 && line[len(line)-1] == '\r' {
		line = line[:len(line)-1]
	}
	return line
}
